int countDivisors(int n) {
    int count = 0;
    for (int i = 1; (long long)i * i <= n; i++) {
        if (n % i == 0) {
            count += (i == n / i) ? 1 : 2;   // i and n/i, unless they are equal
        }
    }
    return count;
}

